<?php

declare(strict_types=1);

namespace LearningMcp;

/**
 * Compiles framework hard constraints from Ai/doc into MCP-facing hard-constraints.v1.
 * Host bootstrap (AGENTS / ensure / session_startup_notices) must stay pointer-only.
 */
final class HardConstraintsCatalog
{
    public const SCHEMA = 'hard-constraints.v1';

    public const AUTHORITATIVE_DOC = 'app/code/Weline/Ai/doc/AI硬规则索引.md';

    public const AUTHORITATIVE_WORKFLOW_DOC = 'app/code/Weline/Ai/doc/AI工程交付流程.md';

    /**
     * Package returned by prepare_project.agent_guidance.hard_constraints.
     * Default form=symbol (HC-SL hot path). Pass form=full for prose bodies (tests/debug).
     *
     * @param array{form?: string}|null $options
     * @return array<string, mixed>
     */
    public static function package(?array $options = null): array
    {
        $form = strtolower(trim((string) ($options['form'] ?? 'symbol')));
        if ($form === 'full') {
            return self::packageFull();
        }

        $rules = HardConstraintsSymbolDsl::symbolRules();
        // Operational ids are already merged into symbolRules via fullRuleIndex;
        // keep a dedicated symbol list for mcp_operational slot (same compile).
        $operational = HardConstraintsSymbolDsl::symbolOperational();
        $ruleIds = array_column($rules, 'id');
        $operationalIds = array_column($operational, 'id');
        // symbolRules includes operational ids — split for package shape parity.
        $operationalSet = array_fill_keys($operationalIds, true);
        $domainRules = array_values(array_filter(
            $rules,
            static fn (array $row): bool => !isset($operationalSet[$row['id']]),
        ));

        $package = [
            'schema' => self::SCHEMA,
            'form' => 'symbol',
            'must_obey' => true,
            'authoritative_doc' => self::AUTHORITATIVE_DOC,
            'authoritative_workflow_doc' => self::AUTHORITATIVE_WORKFLOW_DOC,
            'host_guidance_role' => 'pointer_only',
            'session_startup_notices_role' => 'pointer_only',
            'expand_via' => HardConstraintsSymbolDsl::EXPAND_VIA,
            'language_schema' => HardConstraintsSymbolDsl::LANGUAGE_SCHEMA,
            'language_schema_path' => HardConstraintsSymbolDsl::LANGUAGE_SCHEMA_PATH,
            'legend' => HardConstraintsSymbolDsl::legend(),
            'preamble' => self::preambleSymbol(),
            'rules' => $domainRules,
            'mcp_operational' => $operational,
            // Full Codex delegation body stays in packageFull(); hot path is pointer-only.
            'host_codex_delegation' => [
                'schema_version' => 'host-codex-delegation.v1',
                'form' => 'symbol_pointer',
                'policy_id' => 'host_delegate_explore_plan_review_to_codex_cli',
                'expand_via' => HardConstraintsSymbolDsl::EXPAND_VIA,
                'note' => 'OPT-IN only when user mentions Codex; full policy via expand id host_delegate_explore_plan_review_to_codex_cli or packageFull().',
            ],
            'token_budget' => HardConstraintsSymbolDsl::PACKAGE_TOKEN_BUDGET,
        ];
        $estimated = HardConstraintsSymbolDsl::estimateTokens($package);
        $package['token_usage'] = [
            'estimated' => $estimated,
            'budget' => HardConstraintsSymbolDsl::PACKAGE_TOKEN_BUDGET,
            'budget_exceeded' => $estimated > HardConstraintsSymbolDsl::PACKAGE_TOKEN_BUDGET,
            'estimate_method' => 'serialized_unicode_characters_div_4',
        ];

        return $package;
    }

    /**
     * Full prose package (rules[].summary). For contracts/tests/debug — not prepare hot path.
     *
     * @return array<string, mixed>
     */
    public static function packageFull(): array
    {
        return [
            'schema' => self::SCHEMA,
            'form' => 'full',
            'must_obey' => true,
            'authoritative_doc' => self::AUTHORITATIVE_DOC,
            'authoritative_workflow_doc' => self::AUTHORITATIVE_WORKFLOW_DOC,
            'host_guidance_role' => 'pointer_only',
            'session_startup_notices_role' => 'pointer_only',
            'expand_via' => HardConstraintsSymbolDsl::EXPAND_VIA,
            'preamble' => self::preamble(),
            'rules' => self::rules(),
            'mcp_operational' => self::mcpOperationalRules(),
            'host_codex_delegation' => self::hostCodexDelegation(),
        ];
    }

    public static function preambleSymbol(): string
    {
        return 'HARD CONSTRAINTS HC-SL (hard-constraints.v1 form=symbol): obey formula∧gloss_zh∧legend. '
            . 'Expand full summary ONLY via ' . HardConstraintsSymbolDsl::EXPAND_VIA . ' (≤'
            . HardConstraintsSymbolDsl::EXPAND_IDS_MAX . '/call). '
            . 'Authority ' . self::AUTHORITATIVE_DOC . '. '
            . 'Eng→□(SelfInstall∧Prep); COps→¬Prep; Eng∧Write→□Arch; WebTouch→□WBOP; PlanRev→□(LensE∧LensA∧LensI). '
            . '【硬约束·符号】热路径仅公式+短义；全文用 resolve_task_context.hard_constraint_ids 展开；禁止把 get_indexed_document 当硬规则展开。';
    }

    /**
     * Structured host-vs-Codex CLI work split for prepare_project.agent_guidance.
     * Independent of nested MCP CodexInvoker / knowledge.codex.enabled.
     *
     * @return array<string, mixed>
     */
    public static function hostCodexDelegation(): array
    {
        $policyId = 'host_delegate_explore_plan_review_to_codex_cli';
        $probeSnippet = <<<'SH'
if [ -n "${CODEX_CLI_PATH:-}" ] && [ -x "$CODEX_CLI_PATH" ]; then
  CODEX_BIN="$CODEX_CLI_PATH"
else
  CODEX_BIN="$(command -v codex 2>/dev/null || which codex 2>/dev/null || true)"
fi
SH;
        $planPrompt = '只读探索仓库；禁止改文件/写补丁。输出仅含 Markdown 三级：## 背景 / ## 方案 / ## 细节。'
            . '细节必须具体到文件路径、符号/规则 id、测试断言、验收与 fallback。'
            . '遵守 AGENTS.md 与 MCP hard_constraints；使用 Codex CLI 默认最新模型，禁止指定模型参数。';
        $reviewPrompt = '审查 staged/unstaged/untracked 改动：正确性、回归、安全、硬规则合规、测试缺口；'
            . '按严重程度列 findings；无阻断项时明确写无阻断项。使用 Codex CLI 默认最新模型，禁止指定模型参数。';

        return [
            'schema_version' => 'host-codex-delegation.v1',
            'policy_id' => $policyId,
            'applies_to' => [
                'coding_engineering_hosts',
                'cursor_and_non_codex_hosts_when_user_opts_in_and_cli_available',
            ],
            'exemptions' => [
                'content_ops_skills_skip_mcp',
                'pure_chat_identity_concept_qa',
            ],
            // Default OFF: CLI presence alone MUST NOT auto-delegate. User must opt in this turn.
            'enabled_when' => 'user_explicitly_mentions_codex_and_codex_cli_available_and_host_is_not_codex',
            'opt_in' => [
                'required' => true,
                'gate' => 'user_message_mentions_codex',
                'forbid_auto_delegate_on_cli_presence_alone' => true,
                'default_when_not_mentioned' => 'host_self_explore_plan_review_via_host_plan_mode_for_planning',
                'trigger_tokens' => [
                    'Codex',
                    'codex',
                    'Codex CLI',
                    '用 Codex',
                    '委派 Codex',
                    'codex exec',
                    'codex review',
                ],
                'rationale' => 'Codex CLI delegation is opt-in only. If the user did not mention Codex this turn, the host MUST explore/plan/review itself—never launch `codex` just because the binary exists.',
            ],
            'native_codex_recursion_guard' => [
                'when_host_is_codex' => 'do_not_spawn_nested_codex',
                'action' => 'perform_explore_plan_review_natively_in_current_codex_session',
            ],
            'independent_of_nested_planner' => true,
            'independent_of' => [
                'knowledge.codex.enabled',
                'knowledge.codex.model',
                'CodexInvoker::planDocumentation',
            ],
            'binary_probe_order' => [
                'CODEX_CLI_PATH (executable)',
                'PATH codex via command -v / which',
            ],
            'binary_probe_shell' => $probeSnippet,
            'model_policy' => [
                'model' => 'cli_default',
                'model_argument_forbidden' => true,
                'forbid_flags' => ['-m', '--model'],
                'rationale' => 'Use the installed Codex CLI latest default model; do not pin an outdated model id.',
            ],
            'plan_mode_relationship' => [
                'when_not_opted_in' => 'host_authors_plan_via_host_plan_mode_for_planning',
                'when_opted_in' => [
                    'host_plan_mode_for_planning' => 'container_and_user_approval_gate_only',
                    'forbid_second_host_authored_plan' => true,
                    'cursor_role_after_plan' => 'implement_code_only_from_codex_plan',
                ],
            ],
            // Secondary sync for Codex opt-in plans ONLY — host enforcement is rules[]
            // plan_implementability_checklist + plan_content_focus_only (NOT this array alone).
            'plan_content_contract' => [
                'sections_only' => ['背景', '方案', '细节'],
                'policy' => 'plan_content_focus_only',
                'detail_must_include' => [
                    'files_paths',
                    'symbols_or_rule_ids',
                    'test_assertions',
                    'acceptance',
                    'fallback',
                    'feasibility',
                    'nfr_or_na',
                    'lld_or_na',
                    'env_ci',
                    'milestones_or_na',
                    'release_rollback_or_na',
                ],
                'host_enforcement' => 'plan_implementability_checklist_in_rules_not_this_array',
            ],
            'plan_prompt' => $planPrompt,
            'review_prompt' => $reviewPrompt,
            // User must see that Codex—not the host—is the active worker while CLI runs.
            'user_visible_status' => [
                'required' => true,
                'forbid_silent_delegation' => true,
                'announce_in_chat_before_launch' => true,
                'announce_in_chat_on_complete' => true,
                'announce_in_chat_on_fallback' => true,
                'phases' => ['explore_plan', 'post_implement_review'],
                'must_include_tokens' => ['Codex', '正在工作'],
                'phrases' => [
                    'start_zh' => 'Codex 正在工作：{phase}…',
                    'done_zh' => 'Codex 已完成：{phase}',
                    'fallback_zh' => 'Codex 不可用，已回退宿主：{reason}',
                    'start_en' => 'Codex is working: {phase}…',
                    'done_en' => 'Codex finished: {phase}',
                    'fallback_en' => 'Codex unavailable; host fallback: {reason}',
                ],
                'phase_labels' => [
                    'explore_plan' => '探索与详细计划（codex exec）',
                    'post_implement_review' => '编码后审查（codex review --uncommitted）',
                ],
                'rationale' => 'Silent shell delegation hides who is working; the user must see an explicit Codex-working cue before/while CLI runs and a clear done/fallback cue afterward.',
            ],
            // Executable shell: prompts are piped via printf (not comments). Set REPOSITORY + PLAN_OUTPUT first.
            'plan_command_template' => trim($probeSnippet) . "\n"
                . 'test -n "$CODEX_BIN" || { echo "codex_cli_unavailable"; exit 1; }' . "\n"
                . 'test -n "$REPOSITORY" || { echo "repository_required"; exit 1; }' . "\n"
                . 'test -n "$PLAN_OUTPUT" || { echo "plan_output_required"; exit 1; }' . "\n"
                . 'printf \'%s\\n\' "$PLAN_PROMPT" | "$CODEX_BIN" exec \\' . "\n"
                . '  --cd "$REPOSITORY" \\' . "\n"
                . '  --sandbox read-only \\' . "\n"
                . '  --ephemeral \\' . "\n"
                . '  --output-last-message "$PLAN_OUTPUT" \\' . "\n"
                . '  -c approval_policy="never" \\' . "\n"
                . '  -' . "\n"
                . '# PLAN_PROMPT defaults to agent_guidance.host_codex_delegation.plan_prompt',
            // review --uncommitted cannot take a custom prompt on current Codex CLI; cd into repo first.
            'review_command_template' => trim($probeSnippet) . "\n"
                . 'test -n "$CODEX_BIN" || { echo "codex_cli_unavailable"; exit 1; }' . "\n"
                . 'test -n "$REPOSITORY" || { echo "repository_required"; exit 1; }' . "\n"
                . 'cd "$REPOSITORY" || exit 1' . "\n"
                . '"$CODEX_BIN" review --uncommitted' . "\n"
                . '# optional guidance text: agent_guidance.host_codex_delegation.review_prompt',
            'fallback' => [
                'when' => [
                    'cli_missing',
                    'not_executable',
                    'authentication_failure',
                    'timeout',
                    'invalid_output',
                ],
                'action' => 'host_self_explore_plan_review_via_host_plan_mode_for_planning',
                'must_record_reason' => true,
            ],
            'read' => [
                'agent_guidance.host_codex_delegation',
                'hard_constraints.rules[id=' . $policyId . ']',
                self::AUTHORITATIVE_DOC,
            ],
        ];
    }

