        ];
    }

    /**
     * Index-only hard_rules for workflow_contract.v1 — no summary prose dump.
     * prepare hot path is HC-SL (formula+gloss); full summaries via expand_via.
     *
     * @return array<string, mixed>
     */
    public static function workflowHardRulesRef(): array
    {
        $ruleIds = [];
        foreach (self::rules() as $rule) {
            $id = trim((string) ($rule['id'] ?? ''));
            if ($id !== '') {
                $ruleIds[] = $id;
            }
        }
        $operationalIds = [];
        foreach (self::mcpOperationalRules() as $rule) {
            $id = trim((string) ($rule['id'] ?? ''));
            if ($id !== '') {
                $operationalIds[] = $id;
            }
        }

        return [
            'schema' => 'hard-rules-ref.v1',
            'must_obey' => true,
            'source' => 'prepare_project.agent_guidance.hard_constraints',
            'authoritative_doc' => self::AUTHORITATIVE_DOC,
            'form' => 'symbol',
            'rule_ids' => $ruleIds,
            'operational_ids' => $operationalIds,
            'expand_via' => HardConstraintsSymbolDsl::EXPAND_VIA,
            'detail_via' => [
                HardConstraintsSymbolDsl::EXPAND_VIA,
                'HardConstraintsCatalog::packageFull()',
                self::AUTHORITATIVE_DOC,
            ],
            'note' => 'workflow_contract ships rule ids only. prepare_project hard_constraints is HC-SL (formula+gloss_zh+legend)—NOT full summaries in session. Expand prose via resolve_task_context.hard_constraint_ids or packageFull()/authoritative doc. Surfaces still add task-scoped norms.',
        ];
    }

    /**
     * Flat English hard_rules list (compatibility / contract tests).
     * Prefer workflowHardRulesRef() in workflow_contract payloads.
     *
     * @return list<string>
     */
    public static function workflowHardRules(): array
    {
        $rules = [];
        foreach (self::rules() as $rule) {
            $rules[] = $rule['summary'];
        }
        $rules[] = 'Incomplete verification must be reported explicitly.';
        $rules[] = 'Never claim a multi-todo plan done without per-todo evidence; partial work must list unfinished items in the user report and doc/开发日志.md.';
        $rules[] = 'After implement the Agent MUST self-verify by acceptance tier (UT/RT/WB) before claiming done (agent_self_verify_before_done); never mark acceptance passed/skipped/na without non-empty evidence; incomplete verification → only report 代码已改，验收未完成.';
        $rules[] = 'Verification ordering for every code/logic change (local_verify_before_change_and_after_deploy; content-ops exempt): local verification MUST PASS on this workspace BEFORE the change is finished/committed/pushed/released or deployed; a production release (线上/生产, only when the user explicitly authorized it) requires local PASS → deploy → a SECOND verification run against production on the same pathway with real business evidence; deployed ≠ verified—deploy exit code alone never counts, and failure to re-verify production may only be reported as 已上线，线上复验未完成.';
        $rules[] = 'A code/logic change REPLACES, never stacks (no_legacy_code_accumulation_on_change; content-ops exempt): delete the superseded implementation, dead/legacy branches, orphaned templates/hooks/events/routes/columns, commented-out blocks, unused imports/symbols and duplicate parallel implementations in the SAME change set, leaving zero dangling references (docs/i18n/registries reconciled too); if a legacy path must stay it needs an explicit @deprecated + reason + planned removal and MUST be listed in the closeout unfinished items + doc/开发日志.md—never hide leftovers under an empty 无. FORBID using this to wipe other-session/user dirty work or business data (preserve_dirty_workspace still applies).';
        $rules[] = 'Fix the ROOT CAUSE—never conceal errors, never stack patches (no_error_masking_or_patch_workaround; content-ops exempt): errors MUST surface with the real cause and context—FORBID empty/silent catch, catch→default value then success, @ suppression, silent degradation, fake data, hidden switches, weakening/deleting/skipping assertions or tests, --no-verify, or editing only the error text; FORBID symptom patches (per-site if, hard-coded whitelist to dodge validation, bypassing Provider/Taglib/Event/Service/Query, editing generated/vendor as the fix, duplicate logic); an unfixed or unverified failure may only be reported as failed with the real error + blocked reason. Designed degradation is allowed only when user-visible, configurable, logged/monitored and documented.';
        $rules[] = 'Prefer TDD: write failing tests first (red), implement to green, refactor; done only after real test commands PASS with evidence—never claim done on code-only.';
        $rules[] = 'Module app/code/*/doc/ is authoritative; project-level docs live under dev/docs/ (root docs/ and root doc/ removed).';
        $rules[] = 'Never put <?php or <?= in Weline Taglib / w:* tag attribute values; use @lang, Hook, or body-level HTML attributes with htmlspecialchars.';
        $rules[] = 'Never put <?= or <?php inside comments (//, #, /* */, /** */, HTML <!-- -->); this forbids PHP open tags in comments only—not ordinary commented-out statements like // $x = 1;.';
        $rules[] = 'New/changed explanatory comments and PHPDoc summaries default to Simplified Chinese; prefer friendly readable code that matches surrounding style (clear names, flat flow, no clever over-abstraction); still obey no_php_tags_in_comments.';
        $rules[] = 'Never put unquoted commas inside @lang()/@lang{} source text; commas are argument separators and produce ParseError (use quoted @lang(\'…\') or <lang>…</lang>).';
        $rules[] = 'Theme/widget .phtml must not use inline <script> blocks with <?= or server-side PHP; register external modules in weline.modules.js and load with Weline.declare / data-weline-load / data-weline-declare, plus data-* / data-js-ns / data-uid on the widget root.';
        $rules[] = 'Taglib callback()/runtime_callback() return HTML must not contain literal @static(...); compile only resolves @static in .phtml source AST—callback strings are baked verbatim and browsers 404 on .../@static(Module::css/foo.css). Resolve via Template::fetchTagSource(dir_type_STATICS, Module::path) (see I18n\\Taglib\\Local::resolveModuleStaticUrl) or emit PHP echo in callback output.';
        $rules[] = 'If inline <style>/<script> must remain in layout or partial templates, mark data-no-extract="true"; prefer external assets for widgets injected into data-wslot slots.';
        $rules[] = 'When editing Theme/frontend widgets, layouts, partials, or .phtml, follow the frontend_development surface (Theme开发总指南) and MCP skill weline-theme-development via get_skill; if a host UI/frontend-design skill is also active, theme tokens still win—do not invent colors or spacing.';
        $rules[] = 'Whenever the task mentions CSS or 主题/theme, load UI skill frontend-design + prototype skill prototype + theme skill weline-theme-development (MCP get_skill) before writing styles; theme tokens win (css_or_theme_requires_ui_prototype_theme_skills).';
        $rules[] = 'At requirement start classify work_kind, then run Spec Kit/Kiro-style clarify + use-case spec (requirement_clarify_use_case_spec): feature MUST persist doc/开发/spec/{slug}.md with EARS + UC and status clarified|ready-for-plan before architecture/code; non_feature may skip with rationale≥24; load get_skill(requirement_clarify_use_case) or command 需求澄清与用例规格.';
        $rules[] = 'Analyze FE/BE scope at requirement start (requirement_fe_be_scope_analysis): record fe_be_scope=frontend|backend|both|na with concrete bullets; do not ship one side when both are needed.';
        $rules[] = 'When entity/field change signals fire (e.g. 给订单增加类型), plan.impact_surfaces is mandatory with cross-layer inventory (schema_model/service_api/admin_ui/storefront_ui/i18n/tests_e2e); reject empty-only implicit_requirements; align in_scope layers to dev_tasks (requirement_cross_layer_impact_gate). Prefer framework_candidates.impact_candidates.';
        $rules[] = 'During planning (after clarify when applicable, before business code): Agent itself enables host Plan Mode (host_plan_mode_for_planning)—Cursor SwitchMode target_mode_id=plan—FORBID asking the user to click into Plan Mode—UNLESS plan_complexity=simple with plan_skip_rationale≥24 (single module, ≤~2h, no new extension invention); simple skip does NOT waive team, acceptance, or scheme_requires_architecture_review. Forbid production PHP/phtml/CSS while still planning. After the plan body is complete: plan_complete_self_review_then_implement—self-review under plan_review_three_lenses (engineering + architecture + impact/Cognition) then on 通过/有条件通过 SwitchMode→agent and implement; FORBID waiting for user Build/批准计划/点击计划 to start. On 不通过 or conditions needing a user product decision, stop and report. If host lacks Plan Mode, plan read-only and record unavailable + rationale≥24, then still self-review→implement when eligible.';
        $rules[] = 'Host Codex CLI delegation (host_delegate_explore_plan_review_to_codex_cli): OPT-IN ONLY—FORBID launching `codex` when the user did not mention Codex this turn (CLI presence alone is not enough; default = host self explore/plan/review). When user opts in (Codex / codex / Codex CLI / 用 Codex / 委派 Codex / codex exec / codex review) AND CLI is available on non-Codex hosts (Cursor), delegate explore + detailed 背景/方案/细节 plan (`codex exec` read-only) and post-edit review (`codex review --uncommitted`) to Codex CLI default/latest model—FORBID `-m/--model`; independent of knowledge.codex.enabled; BEFORE each delegated `codex` launch MUST chat-announce `Codex` + `正在工作` (phase named)—FORBID silent delegation; after finish announce `Codex 已完成`; on fallback announce `Codex 不可用，已回退宿主` + reason; Cursor implements code only from that Codex plan; Plan Mode is container/approval only when opted in (no second vague plan); native Codex host MUST NOT spawn nested codex; content_ops/chat exempt; on opted-in CLI failure fallback to host Plan Mode and record reason. See agent_guidance.host_codex_delegation.opt_in + user_visible_status.';
        $rules[] = 'Plan complete → self-review → implement (plan_complete_self_review_then_implement): after plan body is done, Agent MUST self-review under plan_review_three_lenses (engineering + architecture + impact/Cognition) AND plan_implementability_checklist then on pass SwitchMode→agent and code—FORBID asking the user to click 计划/Build/批准 to start; missing checklist → 不通过 (may fill then re-review); user 先别开发 / Codex opt-in approval-container path may still wait.';
        $rules[] = 'Default team (engineering_team_for_new_requirements): only work_scale=tiny → 监工 and every user-facing line starts with 监工: (no Team:); plan_complexity=simple alone is NOT 监工 (it only skips the formal plan); every other ask → team, parent=项目经理 only (Team:项目经理:), one_seat_one_agent (real subagent per seat; forbid parent roleplay), peer_talk_via_channel (channel/{thread}.md + resume peers; forbid forged multi-seat dialogue); relay other Team:{席位}: e.g. Team:架构师: only from real subagent reports. Content-ops (产品优化/新建文章) use neither prefix. Team: requirement_session_dashboard (dev/session/{slug}.md; PM-only bookkeeping; FORBID module doc/) + pm_plan_lifecycle (gaps→staff→monitor→notify_pm DoD check→test→PM recheck→close plan_id; deps-parallel OK); framework_first; seat_skill_mirrors (paste per-seat skill mirror; seat get_skill/Read scoped docs before code); dual_track_all triggered seats (施工+合规复审; fail→rework); component_reuse_or_negotiate (原型∥UI ±主题开发工程师 → component-negotiate.md); team_flow_on_contracts—对齐冻结会 (测试主持) freezes executable UC+contracts.md+deps.md before build; wake-on-deps concurrency; forbid post-dev main-path use-case design; acceptance executes frozen UC only; surfaces.md+components.md+contracts.md+deps.md; ui_prototype_gate_before_test: UI+原型 review (reject→resume development) BEFORE Tester e2e/WB; both pass then test; Tester pass→PM 汇审→then report (acceptance-ui.md / acceptance-prototype.md)—e2e green does not waive; parallel only on non-overlapping frozen tracks; 停工 and wait on architecture contradictions; persist dev/team/{slug}/ + dev/session/{slug}.md (module_doc_forbids_ephemeral_work_artifacts). Framework seats include API, 支付开发工程师, and 数据分析 (Visitor pixel—not framework Event). Subagent closed is not delivery. Local/dev: NEVER ask user for credentials—backend admin/admin, frontend self-create (local_dev_test_accounts_self_serve).';
        $rules[] = 'Requirement session dashboard (requirement_session_dashboard): every executable engineering ask MUST keep repository-root dev/session/{slug}.md (same slug as owning-module doc/开发/spec; template requirement-session.md)—phase/plan_ids/gaps/review index/delivery-notify log; FORBID module doc/session; ONLY PM/监工 edits SESSION; no SESSION → forbid construction; gaps non-empty → forbid claiming done.';
        $rules[] = 'PM plan lifecycle (pm_plan_lifecycle): PM is sole SESSION bookkeeper—review gaps→staff→monitor→every seat delivery notify_pm→DoD check (not code-review substitute)→update SESSION→wake deps (parallel OK)→Tester notify→PM recheck→close plan_id; findings open child plan_ids until test+recheck; rework recorded on SESSION; report only when all plan_ids closed + 汇审 pass.';
        $rules[] = 'REST/BinQuery API (api_rest_in_owning_module): staff Team:API: for Rest OR QueryProvider/BinQuery waves; get_skill(api_sdk_development|weline-api-sdk); Read API接口开发规范 + BinQuery Provider开发指南. Shared Query core: reusable I/O in QueryProvider; thin REST default = #[Acl]+w_query; shells must not reimplement business. Attribute BinQueryOperation DEFAULT DENY (external=false, frontend=false)—opt-in exposure + explicit auth. Rest only in owning Vendor_Module. Per-entry gates: REST Acl; query-bin auth/backend_acl; /bin/query external+API Key scope; CDN public only read+external+cdn+visibility=public—forbid cross-entry bypass. First-party browser I/O = BinQuery (not hand-rolled REST). After Provider edits: framework:compile + query:help. Update owning-module API docs same change set.';
        $rules[] = 'UI page Controllers vs async BinQuery mutations (ui_page_controllers_mutations_via_async_binquery): Controllers MAY render UI pages only; non-UI data create/update/delete (资料更新) MUST use async BinQuery (Weline.Api→query-bin→QueryProvider). FORBID multi-Controller CRUD sprawl for one info domain and FORBID save/delete as Controller actions. Exceptions: multipart/stream, OAuth/token, webhooks, Framework BinQuery gateways.';
        $rules[] = 'Admin manage UI full humanized ops (admin_manage_ui_requires_humanized_full_ops): manage surfaces MUST ship list/find + create + edit + delete/disable + domain-appropriate batch—FORBID create-only or list-without-edit/delete then claim done. Mutations still via async BinQuery. Exceptions: user scope cut, read-only audit/dashboard, singleton config, immutable ledgers.';
